  SimulationEvent,
  type TimelineEntry,
  type TimelineBlock,
} from '@/lib/agent-types'
import type { SimulationState, ConversationMessage } from './types'
import { handleAgentSpawn, handleAgentComplete, handleAgentIdle, handlePermissionRequested, handleModelDetected } from './handle-agent-events'
import { handleToolCallStart, handleToolCallEnd } from './handle-tool-events'
import { handleMessage, handleContextUpdate } from './handle-message-events'
import { handleSubagentDispatch, handleSubagentReturn } from './handle-subagent-events'

export interface ProcessEventContext {
  syncForceSimulation: (agents: Map<string, Agent>, edges: Edge[]) => void
  findToolSlot: (agent: Agent, agents: Map<string, Agent>, toolCalls: Map<string, ToolCallNode>, currentTime: number) => { x: number; y: number }
  getContextWindowSize: (modelId?: string) => number
  blockIdCounter: { current: number }
  skipForceSync: boolean
}

/** Mutable collections that handlers mutate in place during a single processEvent call. */
export interface MutableEventState {
  agents: Map<string, Agent>
  toolCalls: Map<string, ToolCallNode>
  particles: SimulationState['particles']
  edges: Edge[]
  discoveries: SimulationState['discoveries']
  fileAttention: SimulationState['fileAttention']
  timelineEntries: SimulationState['timelineEntries']
  conversations: Map<string, ConversationMessage[]>
}

/** Close the last open block on a timeline entry and push a new one. */
export function pushTimelineBlock(
  entry: TimelineEntry,
  currentTime: number,
  block: Pick<TimelineBlock, 'type' | 'label' | 'color'> & { endTime?: number },
  ctx: ProcessEventContext,
): void {
  const lastBlock = entry.blocks[entry.blocks.length - 1]
  if (lastBlock && !lastBlock.endTime) lastBlock.endTime = currentTime
  entry.blocks.push({
    id: `block-${ctx.blockIdCounter.current++}`,
    type: block.type,
    startTime: currentTime,
    endTime: block.endTime,
    label: block.label,
    color: block.color,
  })
}

/** Shallow-compare two Maps by reference equality of values */
function mapsEqual<K, V>(a: Map<K, V>, b: Map<K, V>): boolean {
  if (a.size !== b.size) return false
  for (const [k, v] of a) if (b.get(k) !== v) return false
  return true
}

export function processEvent(event: SimulationEvent, prev: SimulationState, ctx: ProcessEventContext): SimulationState {
      const state: MutableEventState = {
        agents: new Map(prev.agents),
        toolCalls: new Map(prev.toolCalls),
        particles: [...prev.particles],
        edges: [...prev.edges],
        discoveries: [...prev.discoveries],
        fileAttention: new Map(prev.fileAttention),
        timelineEntries: new Map(prev.timelineEntries),
        conversations: new Map(prev.conversations),
      }

      switch (event.type) {
        case 'agent_spawn':       handleAgentSpawn(event.payload, prev.currentTime, state, ctx); break
        case 'agent_complete':    handleAgentComplete(event.payload, prev.currentTime, state, ctx); break
        case 'agent_idle':        handleAgentIdle(event.payload, state); break
        case 'model_detected':    handleModelDetected(event.payload, state, ctx); break
        case 'tool_call_start':   handleToolCallStart(event.payload, prev.currentTime, state, ctx); break
        case 'tool_call_end':     handleToolCallEnd(event.payload, prev.currentTime, state, ctx); break
        case 'message':           handleMessage(event.payload, prev.currentTime, state); break
        case 'context_update':    handleContextUpdate(event.payload, state); break
        case 'subagent_dispatch': handleSubagentDispatch(event.payload, prev.currentTime, state); break
        case 'subagent_return':   handleSubagentReturn(event.payload, prev.currentTime, state); break
        case 'permission_requested': handlePermissionRequested(event.payload, prev.currentTime, state, ctx); break
      }

      // Stabilize references for unchanged collections to prevent
      // downstream React useMemo/re-render cascades (O(n log n) sorts etc.)
      return {
        ...prev,
        agents: state.agents, toolCalls: state.toolCalls,
        particles: state.particles, edges: state.edges,
        discoveries: state.discoveries,
        fileAttention: mapsEqual(prev.fileAttention, state.fileAttention) ? prev.fileAttention : state.fileAttention,
        timelineEntries: mapsEqual(prev.timelineEntries, state.timelineEntries) ? prev.timelineEntries : state.timelineEntries,
        conversations: mapsEqual(prev.conversations, state.conversations) ? prev.conversations : state.conversations,
      }
}

/**
 * Transcript parsing logic extracted from SessionWatcher.
 *
 * Parses JSONL transcript lines and emits AgentEvents via a delegate,
 * keeping the parsing logic decoupled from file-watching concerns.
 */

import * as path from 'path'
import {
  AgentEvent, PendingToolCall, WatchedSession,
  TranscriptEntry, ToolUseBlock, ToolResultBlock,
  emitSubagentSpawn,
} from './protocol'
import { readFileChunk } from './fs-utils'
import {
  PREVIEW_MAX, ARGS_MAX, RESULT_MAX, MESSAGE_MAX,
  SESSION_LABEL_MAX, SESSION_LABEL_TRUNCATED,
  CHILD_NAME_MAX,
  HASH_PREFIX_MAX,
  ORCHESTRATOR_NAME,
  FAILED_RESULT_MAX,
  SYSTEM_CONTENT_PREFIXES,
  generateSubagentFallbackName,
  resolveSubagentChildName,
} from './constants'
import { summarizeInput, summarizeResult, extractInputData, detectError, buildDiscovery } from './tool-summarizer'
import { estimateTokensFromContent, estimateTokensFromText } from './token-estimator'
import { createLogger } from './logger'

const log = createLogger('TranscriptParser')

export interface TranscriptParserDelegate {
  emit(event: AgentEvent, sessionId?: string): void
  elapsed(sessionId?: string): number
  getSession(sessionId: string): WatchedSession | undefined
  fireSessionLifecycle(event: { type: 'started' | 'ended' | 'updated'; sessionId: string; label: string }): void
  emitContextUpdate(agentName: string, session: WatchedSession, sessionId?: string): void
  /** Re-scan the session's subagents directory for not-yet-tailed transcripts.
   *  Used when a Workflow tool_result arrives, so nested files written after
   *  the last scan are picked up before their nodes are completed. */
  scanSubagents?(sessionId: string): void
}

/** Type guard: check if a value is a non-null object */
function isRecord(v: unknown): v is Record<string, unknown> {
  return v !== null && typeof v === 'object'
}

/** Safely extract trimmed text from a text block */
function safeText(block: unknown): string {
  if (!isRecord(block)) return ''
  return String(block.text || '').trim()
}

/** Safely extract trimmed thinking content from a thinking block */
function safeThinking(block: unknown): string {
  if (!isRecord(block)) return ''
  return String(block.thinking || '').trim()
}

/** Returns the signature string if a thinking block is redacted
 *  (plaintext stripped but signature present, as Opus 4.7+ does), else null. */
function redactedThinkingSignature(block: unknown): string | null {
  if (!isRecord(block)) return null
  if (String(block.thinking || '').trim()) return null
  const sig = block.signature
  return typeof sig === 'string' && sig.length > 0 ? sig : null
}

/** Build the dedup hash key for a thinking block. Prefers the transcript entry
 *  UUID; falls back to a prefix of the content (or signature, for redacted blocks). */
function thinkingHashKey(entryUuid: string | undefined, fallbackSource: string): string {
  return entryUuid
    ? `thinking:${entryUuid}`
    : `thinking:${fallbackSource.slice(0, HASH_PREFIX_MAX)}`
}

/** Placeholder shown for redacted thinking blocks (matches Claude Code's UI label). */
const REDACTED_THINKING_LABEL = 'Thinking...'

/** Claude Code writes placeholder model ids such as `<synthetic>` on locally
 *  generated assistant messages (API errors, interrupts). They are not models. */
function isRealModelId(model: unknown): model is string {
  return typeof model === 'string' && model.length > 0 && !model.startsWith('<')
}

/** What the parent transcript records about an Agent/Task launch in the
 *  entry-level `toolUseResult` field of the user entry carrying its tool_result. */
function parseAgentToolUseResult(toolUseResult: unknown): { isAsync: boolean; model?: string } {
  if (!isRecord(toolUseResult)) return { isAsync: false }
  return {
    isAsync: toolUseResult.status === 'async_launched' || toolUseResult.isAsync === true,
    model: isRealModelId(toolUseResult.resolvedModel) ? toolUseResult.resolvedModel : undefined,
  }
}

const TASK_NOTIFICATION_PREFIX = '<task-notification'

/** Text of a user entry's content, whether a plain string or text blocks. */
function userContentText(content: TranscriptEntry['message']['content']): string {
  if (typeof content === 'string') return content.trim()
  if (!Array.isArray(content)) return ''
  return content.map(safeText).filter(Boolean).join('\n')
}

function xmlTag(text: string, tag: string): string | undefined {
  const match = text.match(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`))
  if (!match) return undefined
  return match[1].replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').trim()
}

/** Parse a `<task-notification>` block (sent when a background task stops). */
export function parseTaskNotification(text: string): { toolUseId: string; status: string; summary: string } | null {
  if (!text.startsWith(TASK_NOTIFICATION_PREFIX)) return null
  const toolUseId = xmlTag(text, 'tool-use-id')
  if (!toolUseId) return null
  return {
    toolUseId,
    status: xmlTag(text, 'status') || 'completed',
    summary: xmlTag(text, 'result') || xmlTag(text, 'summary') || '',
  }
}

export class TranscriptParser {
  /** Per-subagent dedup state for inline progress events, keyed by parentToolUseID */
  private inlineSubagentState = new Map<string, {
    agentName: string
    pending: Map<string, PendingToolCall>
    seen: Set<string>
    seenMessages: Set<string>
  }>()
  /** Maps Agent tool_use ID → resolved child agent name (set in handleToolUse) */
  private subagentChildNames = new Map<string, string>()
  /** Background Agent/Task launches waiting for their <task-notification>, keyed by tool_use ID.
   *  Their tool_result only confirms the launch; the real finish arrives later. */
  private backgroundSubagents = new Map<string, { childName: string; parent: string; sessionId?: string }>()

  constructor(private delegate: TranscriptParserDelegate) {}

  /** Clean up state associated with a completed session to prevent unbounded Map growth.
   *  Pass the session's pending tool_use_ids so we can remove orphaned entries. */
  clearSessionState(pendingToolUseIds: Iterable<string>, sessionId?: string): void {
    for (const toolUseId of pendingToolUseIds) {
      this.inlineSubagentState.delete(toolUseId)
      this.subagentChildNames.delete(toolUseId)
    }
    if (sessionId) {
      for (const [toolUseId, bg] of this.backgroundSubagents) {
        if (bg.sessionId !== sessionId) continue
        this.backgroundSubagents.delete(toolUseId)
        this.subagentChildNames.delete(toolUseId)
        this.inlineSubagentState.delete(toolUseId)
      }
    }
  }

  processTranscriptLine(
    line: string,
    agentName = ORCHESTRATOR_NAME,
    ctxPending: Map<string, PendingToolCall>,
    ctxSeen: Set<string>,
    sessionId?: string,
    ctxSeenMessages?: Set<string>,
  ): void {
    let parsed: Record<string, unknown>
    try {
      parsed = JSON.parse(line.trim()) as Record<string, unknown>
    } catch (err) {
      log.debug('Skipping unparseable line:', err)
      return
    }

    // Handle inline subagent progress events (newer Claude Code versions)
    if (parsed.type === 'progress') {
      this.handleProgressEvent(parsed, sessionId)
      return
    }

    // Only process actual conversation entries (user/assistant turns)
    if (parsed.type !== 'user' && parsed.type !== 'assistant') {
      return
    }

    const msg = parsed.message as TranscriptEntry['message'] | undefined
    if (!msg) { return }

    // Now we know this is a valid transcript entry
    const entry: TranscriptEntry = {
      sessionId: parsed.sessionId as string,
      type: parsed.type as string,
      uuid: parsed.uuid as string | undefined,
      message: msg,
    }

    // A background task finished. Only Agent/Task launches we're tracking are
    // acted on; background Bash and other tasks send the same block. The text
    // itself is still filtered below as system-injected content.
    if (entry.type === 'user') {
      const notification = parseTaskNotification(userContentText(msg.content))
      if (notification) { this.handleTaskNotification(notification, sessionId) }
    }

    // Try to set session label from first user message (for live events after session start)
    if (sessionId) {
      this.maybeSetSessionLabel(entry, sessionId)
    }

    const role = msg.role // 'assistant', 'user', 'human'

    const session = sessionId ? this.delegate.getSession(sessionId) : undefined

    // Extract model from assistant messages (updates tokensMax on the frontend).
    // Per-agent tracking: re-emit when the model changes (e.g. /model switch).
    if (session && entry.type === 'assistant' && isRealModelId(msg.model) && session.modelDetectedAgents.get(agentName) !== msg.model) {
      session.modelDetectedAgents.set(agentName, msg.model)
      if (!session.model) session.model = msg.model
      this.delegate.emit({
        time: this.delegate.elapsed(sessionId),
        type: 'model_detected',
        payload: { agent: agentName, model: msg.model },
      }, sessionId)
    }

    // Dedup set for messages (context compression replays old messages)
    const seenMsgs = ctxSeenMessages ?? session?.seenMessageHashes

    // Handle string content (user messages are often just strings)
    if (typeof msg.content === 'string' && msg.content.trim()) {
      if (role === 'user' || role === 'human') {
        const text = msg.content.trim()
        // Skip system-injected context (continuation summaries, IDE context, etc.)
        if (!this.isSystemInjectedContent(text)) {
          const hash = entry.uuid ? `user:${entry.uuid}` : `user:${text.slice(0, HASH_PREFIX_MAX)}`
          if (seenMsgs && seenMsgs.has(hash)) { /* skip duplicate */ }
          else {
            seenMsgs?.add(hash)
            if (session) { session.contextBreakdown.userMessages += estimateTokensFromText(text) }
            this.delegate.emit({
              time: this.delegate.elapsed(sessionId),
              type: 'message',
              payload: { agent: agentName, role: 'user', content: text.slice(0, MESSAGE_MAX) },
            }, sessionId)
          }
        }
      }
      if (session) { this.delegate.emitContextUpdate(agentName, session, sessionId) }
      return
    }

    if (!Array.isArray(msg.content)) { return }

    // Determine the emitted role from the JSONL entry role
    const emitRole = (role === 'user' || role === 'human') ? 'user' : 'assistant'

    for (const block of msg.content) {
      if (block.type === 'tool_use') {
        const toolBlock = block as ToolUseBlock
        if (ctxSeen.has(toolBlock.id)) { continue }
        ctxSeen.add(toolBlock.id)
        this.handleToolUse(toolBlock, agentName, ctxPending, sessionId)
      } else if (block.type === 'tool_result') {
        this.handleToolResult(block as ToolResultBlock, agentName, ctxPending, sessionId, parsed.toolUseResult)
      } else if (block.type === 'text' && 'text' in block) {
        this.handleTextBlock(block, emitRole, entry.uuid, agentName, seenMsgs, session, sessionId)
      } else if (block.type === 'thinking' && 'thinking' in block) {
        this.handleThinkingBlock(block, entry.uuid, agentName, seenMsgs, session, sessionId)
      }
    }

    if (session) { this.delegate.emitContextUpdate(agentName, session, sessionId) }
  }

  /** Process a text block — dedup, track tokens, emit message event */
  private handleTextBlock(
    block: unknown,
    emitRole: 'user' | 'assistant',
    entryUuid: string | undefined,
    agentName: string,
    seenMsgs: Set<string> | undefined,
    session: WatchedSession | undefined,
    sessionId?: string,
  ): void {
    const text = safeText(block)
    if (!text) return
    // Skip system/IDE context injected into user turns
    if (emitRole === 'user' && this.isSystemInjectedContent(text)) return

    const hash = entryUuid ? `${emitRole}:${entryUuid}` : `${emitRole}:${text.slice(0, HASH_PREFIX_MAX)}`
    if (seenMsgs?.has(hash)) return
    seenMsgs?.add(hash)

    if (session) {
      if (emitRole === 'user') { session.contextBreakdown.userMessages += estimateTokensFromText(text) }
      else { session.contextBreakdown.reasoning += estimateTokensFromText(text) }
    }
    this.delegate.emit({
      time: this.delegate.elapsed(sessionId),
      type: 'message',
      payload: { agent: agentName, role: emitRole, content: text.slice(0, MESSAGE_MAX) },
    }, sessionId)
  }

  /** Process a thinking block — dedup, track tokens, emit message event.
   *  Redacted thinking (Opus 4.7+) is shown as a "Thinking..." placeholder. */
  private handleThinkingBlock(
    block: unknown,
    entryUuid: string | undefined,
    agentName: string,
    seenMsgs: Set<string> | undefined,
    session: WatchedSession | undefined,
    sessionId?: string,
  ): void {
    const thinking = safeThinking(block)
    const redactedSig = thinking ? null : redactedThinkingSignature(block)
    if (!thinking && !redactedSig) return

    const hash = thinkingHashKey(entryUuid, thinking || redactedSig || '')
    if (seenMsgs?.has(hash)) return
    seenMsgs?.add(hash)

    // Reasoning tokens are unknown for redacted blocks — skip breakdown update
    if (session && thinking) { session.contextBreakdown.reasoning += estimateTokensFromText(thinking) }
    this.delegate.emit({
      time: this.delegate.elapsed(sessionId),
      type: 'message',
      payload: {
        agent: agentName,
        role: 'thinking',
        content: thinking ? thinking.slice(0, MESSAGE_MAX) : REDACTED_THINKING_LABEL,
      },
    }, sessionId)
  }

  handleToolUse(
    block: ToolUseBlock,
    agentName: string,
    ctxPending: Map<string, PendingToolCall>,
    sessionId?: string,
  ): void {
    const toolName = block.name
    const args = summarizeInput(toolName, block.input)

    const rawPath = block.input.file_path || block.input.path
    const filePath = typeof rawPath === 'string' ? rawPath : undefined
    ctxPending.set(block.id, {
      name: toolName,
      args,
      filePath,
      startTime: Date.now(),
    })

    // Check if this is a subagent call (Task in older Claude Code, Agent in newer versions)
    if (toolName === 'Task' || toolName === 'Agent') {
      const childName = resolveSubagentChildName(block.input)
      this.subagentChildNames.set(block.id, childName)
      // Only emit spawn once per subagent name (file watcher may have already spawned it)
      const session = sessionId ? this.delegate.getSession(sessionId) : undefined
      if (!session?.spawnedSubagents.has(childName)) {
        session?.spawnedSubagents.add(childName)
        emitSubagentSpawn(this.delegate, agentName, childName, args, sessionId)
      }
    }

    this.delegate.emit({
      time: this.delegate.elapsed(sessionId),
      type: 'tool_call_start',
      payload: {
        agent: agentName,
        tool: toolName,
        args,
        preview: `${toolName}: ${args}`.slice(0, PREVIEW_MAX),
        inputData: extractInputData(toolName, block.input),
      },
    }, sessionId)
  }

  handleToolResult(
    block: ToolResultBlock,
    agentName: string,
    ctxPending: Map<string, PendingToolCall>,
    sessionId?: string,
    toolUseResult?: unknown,
  ): void {
    const pending = ctxPending.get(block.tool_use_id)
    // Skip orphaned tool_results (their tool_use was deduped during catch-up)
    if (!pending) { return }
    const toolName = pending.name
    const result = summarizeResult(block.content)
    const tokenCost = estimateTokensFromContent(block.content)

    // Update context breakdown
    if (sessionId) {
      const session = this.delegate.getSession(sessionId)
      if (session) {
        if (toolName === 'Task' || toolName === 'Agent') {
          session.contextBreakdown.subagentResults += tokenCost
        } else {
          session.contextBreakdown.toolResults += tokenCost
        }
      }
    }

    ctxPending.delete(block.tool_use_id)

    // Build discovery for file-related tools
    const discovery = buildDiscovery(toolName, pending?.filePath || ''

import * as http from 'http'
import * as vscode from 'vscode'
import { AgentEvent, emitSubagentSpawn } from './protocol'
import {
  ORCHESTRATOR_NAME, PREVIEW_MAX, RESULT_MAX,
  SESSION_ID_DISPLAY, FAILED_RESULT_MAX, HOOK_MAX_BODY_SIZE,
  SUBAGENT_ID_SUFFIX_LENGTH, HOOK_SERVER_HOST, HOOK_SERVER_NOT_STARTED,
  generateSubagentFallbackName,
} from './constants'
import { summarizeInput, summarizeResult, extractFilePath, buildDiscovery } from './tool-summarizer'
import { estimateTokenCost } from './token-estimator'
import { createLogger } from './logger'
import { isAllowedHookRequest } from './request-guard'

const log = createLogger('HookServer')

/**
 * Lightweight HTTP server that receives Claude Code hook events.
 *
 * Claude Code hooks POST JSON payloads for events like PreToolUse, PostToolUse,
 * SubagentStart, SubagentStop, SessionStart, Stop, etc.
 *
 * We transform these into AgentEvent format and emit them.
 */

/** Port 0 = let OS assign a random available port */

interface HookPayload {
  session_id: string
  transcript_path?: string
  cwd?: string
  hook_event_name: string
  // PreToolUse / PostToolUse
  tool_name?: string
  tool_input?: Record<string, unknown>
  tool_use_id?: string
  tool_response?: string | { content: string } | Array<{ text?: string }>
  // SubagentStart / SubagentStop
  agent_id?: string
  agent_type?: string
  agent_transcript_path?: string
  // Notification
  notification_type?: string
  message?: string
  title?: string
  // Generic
  [key: string]: unknown
}

export class HookServer implements vscode.Disposable {
  private server: http.Server | null = null
  private port: number
  /** Per-session state — cleaned up on SessionEnd/Stop to prevent unbounded growth */
  private sessionState = new Map<string, {
    startTime: number
    agentNames: Map<string, string> // agent_id → friendly name
  }>()

  private readonly _onEvent = new vscode.EventEmitter<AgentEvent>()

  readonly onEvent = this._onEvent.event

  constructor(port?: number) {
    this.port = port ?? 0
  }

  async start(): Promise<number> {
    return new Promise((resolve, reject) => {
      this.server = http.createServer((req, res) => {
        if (!isAllowedHookRequest(req.headers)) {
          log.warn(`Rejected hook request (host: ${req.headers.host ?? '-'}, origin: ${req.headers.origin ?? '-'})`)
          res.writeHead(403)
          res.end()
          return
        }
        if (req.method === 'POST') {
          let body = ''
          let oversized = false
          req.on('data', (chunk: Buffer) => {
            if (oversized) return
            body += chunk.toString()
            if (body.length > HOOK_MAX_BODY_SIZE) {
              oversized = true
              body = ''
              log.warn('Request body exceeded size limit, discarding')
            }
          })
          req.on('end', () => {
            if (!oversized) {
              try {
                const parsed: unknown = JSON.parse(body)
                if (!parsed || typeof parsed !== 'object' || !('session_id' in parsed) || !('hook_event_name' in parsed)
                    || typeof (parsed as HookPayload).session_id !== 'string'
                    || typeof (parsed as HookPayload).hook_event_name !== 'string') {
                  log.warn('Invalid hook payload: missing session_id or hook_event_name')
                } else {
                  this.handleHook(parsed as HookPayload)
                }
              } catch (e) {
                log.error('Failed to parse payload:', e)
              }
            }
            // Always return 200 with empty body — we're observing, not blocking.
            // Empty body = "success, no output" per Claude Code docs.
            // Returning JSON (even '{}') triggers schema parsing which can cause issues.
            res.writeHead(200)
            res.end()
          })
        } else {
          res.writeHead(200, { 'Content-Type': 'text/plain' })
          res.end('Agent Visualizer Hook Server')
        }
      })

      this.server.on('error', (err: NodeJS.ErrnoException) => {
        if (err.code === 'EADDRINUSE') {
          // Another instance already owns this port — skip instead of incrementing
          // to a port nobody sends to. The session watcher handles all events via JSONL.
          log.info(`Port ${this.port} in use (another instance owns it) — skipping hook server`)
          this.server?.close()
          this.server = null
          resolve(HOOK_SERVER_NOT_STARTED)
        } else {
          reject(err)
        }
      })

      this.server.listen(this.port, HOOK_SERVER_HOST, () => {
        const addr = this.server!.address() as { port: number }
        this.port = addr.port
        log.info(`Listening on http://127.0.0.1:${this.port}`)
        resolve(this.port)
      })
    })
  }

  getPort(): number {
    return this.port
  }

  private getOrCreateSession(sessionId: string): { startTime: number; agentNames: Map<string, string> } {
    let state = this.sessionState.get(sessionId)
    if (!state) {
      state = { startTime: Date.now(), agentNames: new Map() }
      this.sessionState.set(sessionId, state)
    }
    return state
  }

  private elapsedSeconds(sessionId?: string): number {
    const startTime = sessionId ? (this.sessionState.get(sessionId)?.startTime ?? Date.now()) : Date.now()
    return (Date.now() - startTime) / 1000
  }

  private handleHook(payload: HookPayload): void {
    const eventName = payload.hook_event_name
    log.debug(eventName, payload.tool_name || payload.agent_type || '')

    switch (eventName) {
      case 'SessionStart':
        this.handleSessionStart(payload)
        break
      case 'PreToolUse':
        this.handlePreToolUse(payload)
        break
      case 'PostToolUse':
        this.handlePostToolUse(payload)
        break
      case 'PostToolUseFailure':
        this.handlePostToolUseFailure(payload)
        break
      case 'SubagentStart':
        this.handleSubagentStart(payload)
        break
      case 'SubagentStop':
        this.handleSubagentStop(payload)
        break
      case 'Notification':
        this.handleNotification(payload)
        break
      case 'Stop':
        this.handleStop(payload)
        break
      case 'SessionEnd':
        this.handleSessionEnd(payload)
        break
    }
  }

  private handleSessionStart(payload: HookPayload): void {
    this.getOrCreateSession(payload.session_id)

    this.emit({
      time: 0,
      type: 'agent_spawn',
      payload: {
        name: ORCHESTRATOR_NAME,
        isMain: true,
        task: `Session ${payload.session_id.slice(0, SESSION_ID_DISPLAY)}`,
      },
    }, payload.session_id)
  }

  private handlePreToolUse(payload: HookPayload): void {
    const agentName = this.resolveAgentName(payload)
    const toolName = payload.tool_name || 'unknown'
    const args = summarizeInput(toolName, payload.tool_input)

    // If this is the first event and no session start was received, auto-spawn
    if (!this.sessionState.has(payload.session_id)) {
      this.handleSessionStart(payload)
    }

    this.emit({
      time: this.elapsedSeconds(payload.session_id),
      type: 'tool_call_start',
      payload: {
        agent: agentName,
        tool: toolName,
        args,
        preview: `${toolName}: ${args}`.slice(0, PREVIEW_MAX),
      },
    }, payload.session_id)
  }

  private handlePostToolUse(payload: HookPayload): void {
    const agentName = this.resolveAgentName(payload)
    const toolName = payload.tool_name || 'unknown'
    const result = payload.tool_response ? summarizeResult(payload.tool_response) : ''
    const tokenCost = estimateTokenCost(toolName, result)

    // Build discovery for file-related tools
    const discovery = buildDiscovery(toolName, extractFilePath(payload.tool_input), result)

    this.emit({
      time: this.elapsedSeconds(payload.session_id),
      type: 'tool_call_end',
      payload: {
        agent: agentName,
        tool: toolName,
        result: result.slice(0, RESULT_MAX),
        tokenCost,
        ...(discovery ? { discovery } : {}),
      },
    }, payload.session_id)
  }

  private handlePostToolUseFailure(payload: HookPayload): void {
    const agentName = this.resolveAgentName(payload)
    const toolName = payload.tool_name || 'unknown'

    this.emit({
      time: this.elapsedSeconds(payload.session_id),
      type: 'tool_call_end',
      payload: {
        agent: agentName,
        tool: toolName,
        result: `[FAILED] ${(payload.tool_response ? summarizeResult(payload.tool_response) : '').slice(0, FAILED_RESULT_MAX)}`,
        tokenCost: 0,
      },
    }, payload.session_id)
  }

  private handleSubagentStart(payload: HookPayload): void {
    // Track agent_id → name mapping for SubagentStop resolution, but do not
    // emit agent_spawn here.  The transcript parser independently spawns the
    // subagent using its description field (via resolveSubagentChildName),
    // which produces the user-facing name.  Emitting a second spawn from the
    // hook creates a duplicate node with a generic name like
    // "general-purpose-ab75a" alongside the correctly-named node.
    const agentType = payload.agent_type || 'subagent'
    const agentId = payload.agent_id || ''
    const sessionAgents = this.getOrCreateSession(payload.session_id).agentNames
    const childName = agentId ? `${agentType}-${agentId.slice(-SUBAGENT_ID_SUFFIX_LENGTH)}` : generateSubagentFallbackName(String(Date.now()), sessionAgents.size + 1)

    sessionAgents.set(agentId, childName)
  }

  private handleSubagentStop(payload: HookPayload): void {
    const agentId = payload.agent_id || ''
    const sessionAgents = this.sessionState.get(payload.session_id)?.agentNames
    const childName = sessionAgents?.get(agentId) || 'subagent'
    const parentName = this.resolveAgentName(payload)

    this.emit({
      time: this.elapsedSeconds(payload.session_id),
      type: 'subagent_return',
      payload: { child: childName, parent: parentName, summary: `${payload.agent_type} complete` },
    }, payload.session_id)

    this.emit({
      time: this.elapsedSeconds(payload.session_id),
      type: 'agent_complete',
      payload: { name: childName },
    }, payload.session_id)
  }

  private handleNotification(payload: HookPayload): void {
    if (payload.notification_type !== 'permission_prompt') return

    this.emit({
      time: this.elapsedSeconds(payload.session_id),
      type: 'permission_requested',
      payload: {
        agent: ORCHESTRATOR_NAME,
        message: payload.message || 'Permission needed',
        title: payload.title || 'Permission needed',
      },
    }, payload.session_id)
  }

  private handleStop(payload: HookPayload): void {
    this.emit({
      time: this.elapsedSeconds(payload.session_id),
      type: 'agent_complete',
      payload: { name: ORCHESTRATOR_NAME },
    }, payload.session_id)
  }

  private handleSessionEnd(payload: HookPayload): void {
    this.emit({
      time: this.elapsedSeconds(payload.session_id),
      type: 'agent_complete',
      payload: { name: ORCHESTRATOR_NAME, sessionEnd: true },
    }, payload.session_id)

    // Clean up per-session state to prevent unbounded Map growth
    this.sessionState.delete(payload.session_id)
  }

  // ─── Helpers ─────────────────────────────────────────────────────────────

  private resolveAgentName(payload: HookPayload): string {
    // If this event has an agent_id, look it up in the session's agent names.
    if (payload.agent_id) {
      const name = this.sessionState.get(payload.session_id)?.agentNames.get(payload.agent_id)
      if (name) return name
    }
    return ORCHESTRATOR_NAME
  }

  private emit(event: AgentEvent, sessionId?: string): void {
    this._onEvent.fire(sessionId ? { ...event, sessionId } : event)
  }

  dispose(): void {
    if (this.server) {
      this.server.close()
      this.server = null
    }
    this.sessionState.clear()
    this._onEvent.dispose()
  }
}

/**
 * Message protocol between VS Code extension host and webview.
 *
 * Extension → Webview: agent events, state updates, connection status
 * Webview → Extension: user commands (inject, connect/disconnect)
 */

// ─── Agent Event Types (from real agent sessions) ────────────────────────────

export type AgentEventType =
  | 'agent_spawn'
  | 'agent_complete'
  | 'agent_idle'
  | 'message'
  | 'context_update'
  | 'model_detected'
  | 'tool_call_start'
  | 'tool_call_end'
  | 'subagent_dispatch'
  | 'subagent_return'
  | 'permission_requested'
  | 'error'

export interface AgentEvent {
  time: number
  type: AgentEventType
  payload: Record<string, unknown>
  sessionId?: string
}

export interface SessionInfo {
  id: string
  label: string
  status: 'active' | 'completed'
  startTime: number
  lastActivityTime: number
}

// ─── Extension → Webview Messages ────────────────────────────────────────────

export type ExtensionToWebviewMessage =
  | { type: 'connection-status'; status: 'connected' | 'disconnected' | 'watching'; source: string }
  | { type: 'agent-event'; event: AgentEvent }
  | { type: 'agent-event-batch'; events: AgentEvent[] }
  | { type: 'reset'; reason: string }
  | { type: 'config'; config: Partial<VisualizerConfig> }
  | { type: 'session-list'; sessions: SessionInfo[] }
  | { type: 'session-started'; session: SessionInfo }
  | { type: 'session-ended'; sessionId: string }
  | { type: 'session-updated'; sessionId: string; label: string }

export interface VisualizerConfig {
  mode: 'live' | 'replay'
  autoPlay: boolean
  showMockData: boolean
  disable1MContext: boolean
}

// ─── Webview → Extension Messages ────────────────────────────────────────────

export type WebviewToExtensionMessage =
  | { type: 'ready' }
  | { type: 'request-connect' }
  | { type: 'request-disconnect' }
  | { type: 'open-file'; filePath: string; line?: number }
  | { type: 'log'; level: 'info' | 'warn' | 'error'; message: string }

// ─── Transcript Types (from Claude Code JSONL files) ─────────────────────────

export interface TranscriptEntry {
  sessionId: string
  type: string
  uuid?: string
  message: {
    role: string
    model?: string
    content: Array<TranscriptContentBlock> | string
  }
}

export interface ToolUseBlock {
  type: 'tool_use'
  name: string
  id: string
  input: Record<string, unknown>
}

export interface ToolResultBlock {
  type: 'tool_result'
  tool_use_id: string
  content: string | Array<{ text?: string; type?: string }>
}

export interface ThinkingBlock {
  type: 'thinking'
  thinking: string
}

export interface TextBlock {
  type: 'text'
  text: string
}

export type TranscriptContentBlock =
  | ToolUseBlock
  | ToolResultBlock
  | ThinkingBlock
  | TextBlock
  | { type: string; [key: string]: unknown }

// ─── Shared Helpers ─────────────────────────────────────────────────────────

/** Minimal emitter interface used by {@link emitSubagentSpawn}. */
export interface AgentEventEmitter {
  emit(event: AgentEvent, sessionId?: string): void
  elapsed(sessionId?: string): number
}

/**
 * Emit the paired subagent_dispatch + agent_spawn events.
 *
 * This two-event sequence is required every time a subagent is spawned and was
 * previously duplicated in SessionWatcher and TranscriptParser.
 */
export function emitSubagentSpawn(
  emitter: AgentEventEmitter,
  parent: string,
  child: string,
  task: string,
  sessionId?: string,
): void {
  emitter.emit({
    time: emitter.elapsed(sessionId),
    type: 'subagent_dispatch',
    payload: { parent, child, task },
  }, sessionId)
  emitter.emit({
    time: emitter.elapsed(sessionId),
    type: 'agent_spawn',
    payload: { name: child, parent, task },
  }, sessionId)
}

// ─── Shared Internal Types ───────────────────────────────────────────────────

/** A tool call that has started but not yet received its result */
export interface PendingToolCall {
  name: string
  args: string
  filePath?: string
  startTime: number
}

// ─── Session Types ──────────────────────────────────────────────────────────

export interface SubagentState {
  watcher: import('fs').FSWatcher | null
  fileSize: number
  /** Incomplete trailing JSONL record carried between reads. */
  fileTail: string
  agentName: string
  pendingToolCalls: Map<string, PendingToolCall>
  seenToolUseIds: Set<string>
  permissionTimer: NodeJS.Timeout | null
  permissionEmitted: boolean
  spawnEmitted: boolean
  /** Node has been completed (Workflow subagents complete when their Workflow
   *  tool_result arrives). Cleared if the transcript starts growing again. */
  completed: boolean
}

/** State tracked for a single watched Claude Code session */
export interface WatchedSession {
  sessionId: string
  filePath: string
  fileWatcher: import('fs').FSWatcher | null
  pollTimer: NodeJS.Timeout | null
  fileSize: number
  /** Incomplete trailing JSONL record carried between reads. */
  fileTail: string
  sessionStartTime: number
  pendingToolCalls: Map<string, PendingToolCall>
  seenToolUseIds: Set<string>
  seenMessageHashes: Set<string>
  sessionDetected: boolean
  sessionCompleted: boolean
  lastActivityTime: number
  inactivityTimer: NodeJS.Timeout | null
  subagentWatchers: Map<string, SubagentState>
  /** Names of subagents already spawned (by transcript parser or file watcher) — prevents duplicate spawns */
  spawnedSubagents: Set<string>
  /** Subagent names currently receiving inline progress events — file watcher skips these */
  inlineProgressAgents: Set<string>
  subagentsDirWatcher: import('fs').FSWatcher | null
  subagentsDir: string | null
  label: string
  labelSet: boolean
  model: string | null
  /** Maps agent names to their last emitted model ID — re-emits on model change */
  modelDetectedAgents: Map<string, string>
  permissionTimer: NodeJS.Timeout | null
  permissionEmitted: boolean
  contextBreakdown: {
    systemPrompt: number
    userMessages: number
    toolResults: number
    reasoning: number
    subagentResults: number
  }
}

// ─── Claude Settings Types ──────────────────────────────────────────────────

export interface ClaudeHookDef {
  type?: string
  url?: string
  command?: string
  timeout?: number
}

export interface ClaudeHookEntry {
  hooks?: ClaudeHookDef[]
}

/**
 * Unit tests for TranscriptParser's subagent lifecycle and model detection.
 *
 * Background Agent/Task launches (the Claude Code default) return a
 * tool_result right away that only confirms the launch. The subagent really
 * finishes when a <task-notification> for its tool_use_id arrives (#92).
 * The launch result also carries the subagent's resolved model (#91).
 */

import { describe, it } from 'node:test'
import assert from 'node:assert/strict'
import * as fs from 'node:fs'
import * as os from 'node:os'
import * as path from 'node:path'
import { TranscriptParser, TranscriptParserDelegate, parseTaskNotification } from '../src/transcript-parser'
import { AgentEvent, WatchedSession } from '../src/protocol'

const SESSION_ID = 'session-1'

function makeSession(): WatchedSession {
  return {
    sessionId: SESSION_ID,
    filePath: '/tmp/session-1.jsonl',
    fileWatcher: null,
    pollTimer: null,
    fileSize: 0,
    fileTail: '',
    sessionStartTime: Date.now(),
    pendingToolCalls: new Map(),
    seenToolUseIds: new Set(),
    seenMessageHashes: new Set(),
    sessionDetected: true,
    sessionCompleted: false,
    lastActivityTime: Date.now(),
    inactivityTimer: null,
    subagentWatchers: new Map(),
    spawnedSubagents: new Set(),
    inlineProgressAgents: new Set(),
    subagentsDirWatcher: null,
    subagentsDir: null,
    label: 'Session',
    labelSet: true,
    model: null,
    modelDetectedAgents: new Map(),
    permissionTimer: null,
    permissionEmitted: false,
    contextBreakdown: { systemPrompt: 0, userMessages: 0, toolResults: 0, reasoning: 0, subagentResults: 0 },
  }
}

function setup() {
  const session = makeSession()
  const events: AgentEvent[] = []
  const delegate: TranscriptParserDelegate = {
    emit: (event) => { events.push(event) },
    elapsed: () => 0,
    getSession: (id) => (id === SESSION_ID ? session : undefined),
    fireSessionLifecycle: () => {},
    emitContextUpdate: () => {},
  }
  const parser = new TranscriptParser(delegate)
  const feed = (entry: unknown, agent = 'orchestrator') => parser.processTranscriptLine(
    JSON.stringify(entry), agent, session.pendingToolCalls, session.seenToolUseIds, SESSION_ID, session.seenMessageHashes,
  )
  return { session, events, parser, feed }
}

function agentToolUse(id: string, description: string) {
  return {
    type: 'assistant', uuid: `a-${id}`,
    message: { role: 'assistant', model: 'claude-opus-5-5', content: [
      { type: 'tool_use', id, name: 'Agent', input: { description, subagent_type: 'Explore', prompt: 'look around' } },
    ] },
  }
}

function agentToolResult(id: string, toolUseResult?: unknown) {
  return {
    type: 'user', uuid: `r-${id}`,
    message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: id, content: 'Async agent launched successfully.' }] },
    ...(toolUseResult ? { toolUseResult } : {}),
  }
}

function asyncLaunch(resolvedModel = 'claude-sonnet-5[1m]') {
  return { isAsync: true, status: 'async_launched', agentId: 'abc123', description: 'Find callers', resolvedModel }
}

function taskNotification(toolUseId: string, status = 'completed', result = 'Found 3 callers.') {
  return {
    type: 'user', uuid: `n-${toolUseId}-${status}`, origin: { kind: 'task-notification' },
    message: { role: 'user', content: [
      '<task-notification>',
      '<task-id>abc123</task-id>',
      `<tool-use-id>${toolUseId}</tool-use-id>`,
      `<status>${status}</status>`,
      '<summary>Agent "Find callers" finished</summary>',
      `<result>${result}</result>`,
      '</task-notification>',
    ].join('\n') },
  }
}

const ofType = (events: AgentEvent[], type: string) => events.filter(e => e.type === type)

describe('background subagents (#92)', () => {
  it('does not complete a background subagent at launch', () => {
    const { events, feed } = setup()
    feed(agentToolUse('toolu_1', 'Find callers'))
    feed(agentToolResult('toolu_1', asyncLaunch()))

    assert.equal(ofType(events, 'agent_spawn').length, 1)
    assert.equal(ofType(events, 'agent_complete').length, 0)
    assert.equal(ofType(events, 'subagent_return').length, 0)
    // The Agent tool call itself still ends (the launch finished)
    assert.equal(ofType(events, 'tool_call_end').length, 1)
  })

  it('completes it when its task-notification arrives', () => {
    const { events, feed } = setup()
    feed(agentToolUse('toolu_1', 'Find callers'))
    feed(agentToolResult('toolu_1', asyncLaunch()))
    feed(taskNotification('toolu_1'))

    assert.deepEqual(ofType(events, 'subagent_return').map(e => e.payload), [
      { child: 'Find callers', parent: 'orchestrator', summary: 'Found 3 callers.' },
    ])
    assert.deepEqual(ofType(events, 'agent_complete').map(e => e.payload), [{ name: 'Find callers' }])
    // The notification is not shown as a user message
    assert.equal(ofType(events, 'message').length, 0)
  })

  it('marks non-completed statuses in the return summary', () => {
    const { events, feed } = setup()
    feed(agentToolUse('toolu_1', 'Find callers'))
    feed(agentToolResult('toolu_1', asyncLaunch()))
    feed(taskNotification('toolu_1', 'failed', 'Ran out of turns'))

    assert.equal(ofType(events, 'subagent_return')[0].payload.summary, '[failed] Ran out of turns')
    assert.equal(ofType(events, 'agent_complete').length, 1)
  })

  it('ignores notifications for other background tasks and repeats', () => {
    const { events, feed } = setup()
    feed(agentToolUse('toolu_1', 'Find callers'))
    feed(agentToolResult('toolu_1', asyncLaunch()))
    feed(taskNotification('toolu_bash'))
    assert.equal(ofType(events, 'agent_complete').length, 0)

    feed(taskNotification('toolu_1'))
    feed({ ...taskNotification('toolu_1'), uuid: 'n-again' })
    assert.equal(ofType(events, 'agent_complete').length, 1)
  })

  it('still completes foreground subagents on their tool_result', () => {
    const { events, feed } = setup()
    feed(agentToolUse('toolu_1', 'Find callers'))
    feed(agentToolResult('toolu_1', { status: 'completed', content: [] }))

    assert.deepEqual(ofType(events, 'agent_complete').map(e => e.payload), [{ name: 'Find callers' }])
  })

  it('completes subagents launched before attach once their notification arrives', () => {
    const { session, events, parser, feed } = setup()
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'agent-flow-parser-'))
    const file = path.join(dir, 'session.jsonl')
    const history = [
      agentToolUse('toolu_old', 'Already done'),
      agentToolResult('toolu_old', asyncLaunch()),
      taskNotification('toolu_old'),
      agentToolUse('toolu_live', 'Still running'),
      agentToolResult('toolu_live', asyncLaunch()),
    ].map(e => JSON.stringify(e)).join('\n') + '\n'
    fs.writeFileSync(file, history)
    parser.prescanExistingContent(file, Buffer.byteLength(history), session)

    feed({ ...taskNotification('toolu_old'), uuid: 'n-old-repeat' })
    assert.equal(ofType(events, 'agent_complete').length, 0)

    feed(taskNotification('toolu_live'))
    assert.deepEqual(ofType(events, 'agent_complete').map(e => e.payload), [{ name: 'Still running' }])
  })
})

describe('subagent model (#91)', () => {
  it("emits the subagent's resolved model from the launch result", () => {
    const { events, feed } = setup()
    feed(agentToolUse('toolu_1', 'Find callers'))
    feed(agentToolResult('toolu_1', asyncLaunch('claude-sonnet-5[1m]')))

    const childModels = ofType(events, 'model_detected').filter(e => e.payload.agent === 'Find callers')
    assert.deepEqual(childModels.map(e => e.payload.model), ['claude-sonnet-5[1m]'])
  })

  it("doesn't override a model the subagent's own transcript reported", () => {
    const { session, events, feed } = setup()
    feed(agentToolUse('toolu_1', 'Find callers'))
    session.modelDetectedAgents.set('Find callers', 'claude-haiku-4-5')
    feed(agentToolResult('toolu_1', asyncLaunch('claude-sonnet-5')))

    assert.equal(ofType(events, 'model_detected').filter(e => e.payload.agent === 'Find callers').length, 0)
  })

  it('ignores <synthetic> placeholder models', () => {
    const { session, events, feed } = setup()
    feed({ type: 'assistant', uuid: 'a1', message: { role: 'assistant', model: 'claude-opus-5-5', content: [{ type: 'text', text: 'hi' }] } })
    feed({ type: 'assistant', uuid: 'a2', message: { role: 'assistant', model: '<synthetic>', content: [{ type: 'text', text: 'API Error' }] } })
    feed(agentToolUse('toolu_1', 'Find callers'))
    feed(agentToolResult('toolu_1', asyncLaunch('<synthetic>')))

    assert.deepEqual(ofType(events, 'model_detected').map(e => e.payload), [{ agent: 'orchestrator', model: 'claude-opus-5-5' }])
    assert.equal(session.modelDetectedAgents.get('orchestrator'), 'claude-opus-5-5')
  })

  it('ignores <synthetic> when picking the session model during prescan', () => {
    const { session, parser } = setup()
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'agent-flow-parser-'))
    const file = path.join(dir, 'session.jsonl')
    const history = [
      { type: 'assistant', uuid: 'a1', message: { role: 'assistant', model: '<synthetic>', content: [{ type: 'text', text: 'API Error' }] } },
      { type: 'assistant', uuid: 'a2', message: { role: 'assistant', model: 'claude-opus-5-5', content: [{ type: 'text', text: 'hi' }] } },
    ].map(e => JSON.stringify(e)).join('\n') + '\n'
    fs.writeFileSync(file, history)
    parser.prescanExistingContent(file, Buffer.byteLength(history), session)
    assert.equal(session.model, 'claude-opus-5-5')
  })
})

describe('parseTaskNotification', () => {
  it('extracts the tool use id, status and result', () => {
    const text = taskNotification('toolu_9', 'killed', 'a &gt; b').message.content as string
    assert.deepEqual(parseTaskNotification(text), { toolUseId: 'toolu_9', status: 'killed', summary: 'a > b' })
  })

  it('returns null for other content', () => {
    assert.equal(parseTaskNotification('hello'), null)
    assert.equal(parseTaskNotification('<task-notification>\n<status>completed</status>'), null)
  })
})
